CREATE FUNCTION zoi.studio_media_receipt_guard()RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=''AS $$
DECLARE g zoi.studio_media_events;
BEGIN
 IF NOT pg_try_advisory_xact_lock(hashtextextended('business-creative:'||NEW.request_id::text,0))THEN RAISE EXCEPTION 'studio_media_request_busy';END IF;
 FOR g IN SELECT *FROM zoi.studio_media_events WHERE request_id=NEW.request_id AND phase='grant'LOOP
  IF NEW.actor_auth IS DISTINCT FROM g.actor_auth OR NEW.workspace_id IS DISTINCT FROM g.workspace_id OR NEW.listing_id IS DISTINCT FROM g.listing_id THEN RAISE EXCEPTION 'studio_media_receipt_scope_conflict';END IF;
  IF NEW.state='saved'AND encode(sha256(convert_to(NEW.payload::text,'UTF8')),'hex')IS DISTINCT FROM g.context_hash THEN RAISE EXCEPTION 'studio_media_receipt_payload_conflict';END IF;
 END LOOP;
 RETURN NEW;
END$$;

CREATE FUNCTION zoi.studio_storage_path(value text)RETURNS text LANGUAGE plpgsql IMMUTABLE SET search_path=''AS $$
DECLARE prefix constant text:='https://csebihpaychdkanjjsmz.supabase.co/storage/v1/object/public/media/';raw text;bytes bytea:=''::bytea;i integer:=1;c text;path text;
BEGIN
 IF value IS NULL OR left(value,length(prefix))<>prefix THEN RAISE EXCEPTION 'studio_media_invalid_source_path';END IF;
 raw:=substr(value,length(prefix)+1);
 IF length(raw)>6000 OR raw~'[?#]'THEN RAISE EXCEPTION 'studio_media_invalid_source_path';END IF;
 WHILE i<=length(raw)LOOP c:=substr(raw,i,1);IF c='%'THEN IF substr(raw,i+1,2)!~'^[a-fA-F0-9]{2}$'THEN RAISE EXCEPTION 'studio_media_invalid_source_path';END IF;bytes:=bytes||decode(substr(raw,i+1,2),'hex');i:=i+3;ELSE bytes:=bytes||convert_to(c,'UTF8');i:=i+1;END IF;END LOOP;
 path:=convert_from(bytes,'UTF8');
 IF length(path)NOT BETWEEN 1 AND 1800 OR path~'(^/|/$|//|(^|/)\.\.?(/|$)|[[:cntrl:]\\])'THEN RAISE EXCEPTION 'studio_media_invalid_source_path';END IF;
 RETURN path;
END$$;

CREATE FUNCTION zoi.studio_object(path text,locked boolean DEFAULT false)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=''AS $$
DECLARE r record;result jsonb;count integer:=0;
BEGIN
 IF locked THEN
  FOR r IN SELECT *FROM storage.objects WHERE bucket_id='media'AND name=path AND archived_at IS NULL AND NOT is_delete_marker FOR SHARE LOOP
   count:=count+1;result:=jsonb_build_object('id',r.id,'version',r.version,'updated_at',r.updated_at,'created_at',r.created_at,'metadata',r.metadata,'owner',r.owner,'owner_id',r.owner_id);
  END LOOP;
 ELSE
  FOR r IN SELECT *FROM storage.objects WHERE bucket_id='media'AND name=path AND archived_at IS NULL AND NOT is_delete_marker LOOP
   count:=count+1;result:=jsonb_build_object('id',r.id,'version',r.version,'updated_at',r.updated_at,'created_at',r.created_at,'metadata',r.metadata,'owner',r.owner,'owner_id',r.owner_id);
  END LOOP;
 END IF;
 IF count>1 THEN RAISE EXCEPTION 'studio_media_ambiguous_object';END IF;RETURN result;
END$$;

CREATE OR REPLACE FUNCTION zoi.assert_workspace_write(p_workspace uuid, p_roles text[] DEFAULT ARRAY['owner'::text, 'admin'::text, 'editor'::text])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r text;
begin r:=zoi.workspace_locked_role(p_workspace);
 if not coalesce(r=any(p_roles),false) then raise exception 'insufficient_permission' using errcode='42501';end if;
end $function$

CREATE OR REPLACE FUNCTION zoi.home_content_authorize(p_workspace uuid, p_listing uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE actor uuid:=zoi.org_actor();owner_ws uuid;
BEGIN
 IF actor IS NULL THEN RAISE EXCEPTION 'not_authorized' USING errcode='42501';END IF;
 -- Verify the current account/session before any caller can return an old receipt.
 PERFORM zoi.workspace_invitation_email(false);
 PERFORM 1 FROM zoi.user_profiles WHERE id=actor FOR UPDATE;
 IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM zoi.user_profiles WHERE id=actor AND auth_user_id=auth.uid()) THEN RAISE EXCEPTION 'not_authorized' USING errcode='42501';END IF;
 -- The guard is VOLATILE and uses fresh statements after every existing lock wait.
 PERFORM zoi.workspace_invitation_email(false);
 PERFORM 1 FROM zoi.workspace_members WHERE workspace_id=p_workspace AND profile_id=actor AND role IN('owner','admin','editor')FOR SHARE;IF NOT FOUND THEN RAISE EXCEPTION 'not_authorized' USING errcode='42501';END IF;
 PERFORM zoi.workspace_invitation_email(false);
 SELECT owner_workspace_id INTO owner_ws FROM zoi.listings WHERE id=p_listing FOR UPDATE;
 IF NOT FOUND OR (owner_ws IS NOT NULL AND owner_ws<>p_workspace) OR NOT zoi.bizpage_can_edit(p_workspace,p_listing)THEN RAISE EXCEPTION 'no_access_to_listing' USING errcode='42501';END IF;
 PERFORM zoi.workspace_invitation_email(false);
 IF owner_ws IS NULL THEN PERFORM 1 FROM zoi.listing_claims WHERE listing_id=p_listing AND workspace_id=p_workspace AND claim_status IN('approved','verified')FOR SHARE;IF NOT FOUND THEN RAISE EXCEPTION 'no_access_to_listing' USING errcode='42501';END IF;
 PERFORM zoi.workspace_invitation_email(false);END IF;
 RETURN actor;
END $function$

CREATE OR REPLACE FUNCTION zoi.suite_current_session()
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare sid text:=auth.jwt()->>'session_id';
begin
 if auth.uid() is null or coalesce(sid,'') !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' then raise exception 'suite_session_unavailable' using errcode='42501';end if;
 perform 1 from auth.users where id=auth.uid() and deleted_at is null and coalesce(is_anonymous,false)=false and (banned_until is null or banned_until<=clock_timestamp());
 if not found then raise exception 'suite_session_unavailable' using errcode='42501';end if;
 perform 1 from auth.sessions where id=sid::uuid and user_id=auth.uid() and (not_after is null or not_after>clock_timestamp());
 if not found then raise exception 'suite_session_unavailable' using errcode='42501';end if;
end $function$
